"""
Demo A — Berggren descent and address extraction, verified round-trip.

Shows that the single formula
    P(a, b, c) = (|a+2b-2c|, |2a+b-2c|, 3c-2a-2b)
undoes whichever of the three Berggren moves produced the triple, that the sign
pattern of (u, v) = (a+2b-2c, 2a+b-2c) names that move, and that the resulting
word <-> triple correspondence is a bijection.  It then confirms, by exhaustive
search, that the tree rooted at (3,4,5) contains exactly the primitive
Pythagorean triples with odd first leg.
"""

from __future__ import annotations

from math import gcd, isqrt
from typing import List, Optional, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)


def is_ppt(t: Triple) -> bool:
    a, b, c = t
    return (a > 0 and b > 0 and c > 0 and a * a + b * b == c * c
            and gcd(a, b) == 1 and a % 2 == 1)


def berg(letter: str, t: Triple) -> Triple:
    a, b, c = t
    if letter == "A":
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if letter == "B":
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def uvh(t: Triple) -> Triple:
    a, b, c = t
    return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, 3 * c - 2 * a - 2 * b)


def parent(t: Triple) -> Triple:
    u, v, h = uvh(t)
    return (abs(u), abs(v), h)


def last_move(t: Triple) -> Optional[str]:
    if t == ROOT:
        return None
    u, v, _ = uvh(t)
    return "A" if (u > 0 and v < 0) else "B" if (u > 0 and v > 0) else "C"


def addr(word: str) -> Triple:
    t = ROOT
    for letter in reversed(word):
        t = berg(letter, t)
    return t


def address_of(t: Triple) -> str:
    letters: List[str] = []
    while t != ROOT:
        letters.append(last_move(t))  # type: ignore[arg-type]
        t = parent(t)
    return "".join(letters)


def tree_up_to(limit: int) -> List[Triple]:
    out, frontier = [], [ROOT]
    while frontier:
        nxt = []
        for t in frontier:
            if t[2] <= limit:
                out.append(t)
                nxt += [berg(m, t) for m in "ABC"]
        frontier = nxt
    return sorted(out, key=lambda t: (t[2], t[0]))


def brute_force(limit: int) -> List[Triple]:
    out = []
    for c in range(1, limit + 1):
        for a in range(1, c):
            b = isqrt(c * c - a * a)
            if b > 0 and a * a + b * b == c * c and is_ppt((a, b, c)):
                out.append((a, b, c))
    return sorted(out, key=lambda t: (t[2], t[0]))


def main() -> None:
    print("Descent table:  triple -> (u, v, h) -> sign -> move -> parent")
    for t in [(5, 12, 13), (21, 20, 29), (15, 8, 17), (7, 24, 25), (119, 120, 169)]:
        u, v, h = uvh(t)
        sign = f"({'+' if u > 0 else '-'},{'+' if v > 0 else '-'})"
        print(f"  {str(t):<16} u={u:>5} v={v:>5} h={h:>5}  {sign}  "
              f"{last_move(t)}  -> {parent(t)}")

    print("\nRound-trip on all words of length <= 6:")
    words = [""]
    for _ in range(6):
        words += [w + s for w in words if True for s in "ABC"]
    words = sorted(set(w for w in words if len(w) <= 6), key=lambda w: (len(w), w))
    seen = {}
    for w in words:
        t = addr(w)
        assert t not in seen, f"collision {w} / {seen[t]}"
        seen[t] = w
        assert address_of(t) == w
    print(f"  {len(words)} words -> {len(seen)} distinct triples, "
          f"and address_of(addr(w)) == w throughout.  Bijection confirmed.")

    print("\nClassification check (tree nodes == primitive triples):")
    for limit in (100, 500, 2000):
        assert tree_up_to(limit) == brute_force(limit)
        print(f"  hypotenuse <= {limit:>4}: {len(tree_up_to(limit)):>4} triples, "
              f"both methods agree.")

    print("\nWorst-case descent length: the A-spine.")
    for d in (1, 5, 20, 100):
        t = addr("A" * d)
        assert t == (2 * d + 3, 2 * d * d + 6 * d + 4, 2 * d * d + 6 * d + 5)
        print(f"  depth {d:>3}: {t}   (hypotenuse ~ 2d^2, so depth ~ sqrt(c/2))")


if __name__ == "__main__":
    main()

"""
Demo B — The exact length function of the Pythagorean Hydra.

Heads are primitive Pythagorean triples; chopping a head lets the hydra regrow at
most k heads, each a Berggren ancestor of the chopped one.  The potential
    Phi_k(H) = sum over heads of  phi_k(depth) ,   phi_k(n) = 1 + k + ... + k^n
drops by at least one per move, and there is always a move dropping it by exactly
one.  Hence the longest battle from H has exactly Phi_k(H) moves.  This demo
plays the games and checks the closed form, including a multi-head hydra and the
inert root.  It also contrasts the sharp depth-based bound with the much weaker
bound obtained by using the hypotenuse as the level of a head.
"""

from __future__ import annotations

from typing import List, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)


def berg(letter: str, t: Triple) -> Triple:
    a, b, c = t
    if letter == "A":
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if letter == "B":
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def parent(t: Triple) -> Triple:
    a, b, c = t
    return (abs(a + 2 * b - 2 * c), abs(2 * a + b - 2 * c), 3 * c - 2 * a - 2 * b)


def depth(t: Triple) -> int:
    d = 0
    while t != ROOT:
        t = parent(t)
        d += 1
    return d


def addr(word: str) -> Triple:
    t = ROOT
    for letter in reversed(word):
        t = berg(letter, t)
    return t


def phi(k: int, n: int) -> int:
    return sum(k ** i for i in range(n + 1))


def Phi(k: int, heads: List[Triple]) -> int:
    return sum(phi(k, depth(t)) for t in heads)


def play_worst_case(k: int, heads: List[Triple]) -> int:
    """Chop a head, regrow k copies of its parent: potential falls by exactly 1."""
    heads = list(heads)
    moves = 0
    while heads:
        t = heads.pop()
        if t != ROOT:
            heads.extend([parent(t)] * k)
        moves += 1
    return moves


def main() -> None:
    print("Longest battle against a single head, by depth d and branching bound k")
    print("      k=1     k=2     k=3     k=4     k=5")
    for d in range(7):
        head = addr("B" * d)
        row = []
        for k in range(1, 6):
            played = play_worst_case(k, [head])
            assert played == phi(k, d) == Phi(k, [head])
            row.append(played)
        print(f"  d={d}" + "".join(f"{x:>8}" for x in row))

    print("\nMulti-head hydra {addr(BB), addr(ACB), (3,4,5), addr(A)}:")
    hydra = [addr("BB"), addr("ACB"), ROOT, addr("A")]
    for k in (1, 2, 3, 4):
        played = play_worst_case(k, hydra)
        assert played == Phi(k, hydra)
        print(f"  k={k}: predicted Phi = {Phi(k, hydra):>4}, played battle = {played:>4}")

    print("\nThe root is inert; and the hydra may also regrow nothing:")
    print(f"  battle from {{(3,4,5)}} with k=9: {play_worst_case(9, [ROOT])} move")
    print(f"  shortest possible battle from the 4-head hydra: {len(hydra)} moves")

    print("\nDepth versus hypotenuse as the level of a head (k = 3):")
    print(f"  sharp bound for (3,4,5)   : {phi(3, depth(ROOT))}")
    print(f"  hypotenuse-based bound    : {phi(3, ROOT[2])}  = 1+3+9+27+81+243")
    print("  Both are valid; only the depth-based one is attained.")

    print("\nElementary envelope: phi_k(d) <= (k+1)^(d+1)")
    for k, d in [(2, 5), (3, 6), (4, 8)]:
        print(f"  k={k}, d={d}: {phi(k, d):>8} <= {(k + 1) ** (d + 1):>10}")


if __name__ == "__main__":
    main()

