from math import gcd
from typing import List, Optional, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)


def is_ppt(t: Triple) -> bool:
    """Normalised primitive Pythagorean triple: positive entries, a^2+b^2=c^2,
    gcd(a, b) = 1, first leg odd.  This elementary test decides membership in the
    Berggren tree."""
    a, b, c = t
    return (a > 0 and b > 0 and c > 0 and a * a + b * b == c * c
            and gcd(a, b) == 1 and a % 2 == 1)


def descent_coordinates(t: Triple) -> Triple:
    """(u, v, h) = (a+2b-2c, 2a+b-2c, 3c-2a-2b)."""
    a, b, c = t
    return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, 3 * c - 2 * a - 2 * b)


def parent(t: Triple) -> Triple:
    """The uniform parent map P(a,b,c) = (|u|, |v|, h)."""
    u, v, h = descent_coordinates(t)
    return (abs(u), abs(v), h)


def last_move(t: Triple) -> Optional[str]:
    """The Berggren move that produced t, read off the sign pattern of (u, v):
    (+,-) -> A, (+,+) -> B, (-,+) -> C.  None at the root."""
    if t == ROOT:
        return None
    u, v, _ = descent_coordinates(t)
    if u > 0 and v < 0:
        return "A"
    if u > 0 and v > 0:
        return "B"
    if u < 0 and v > 0:
        return "C"
    raise ValueError(f"unreachable sign pattern for {t}")


def address_of(t: Triple) -> str:
    """The unique address word of a Berggren triple, read right to left from the
    root.  Raises if t is not a normalised primitive triple."""
    if not is_ppt(t):
        raise ValueError(f"{t} is not a node of the Berggren tree")
    letters: List[str] = []
    while t != ROOT:
        letters.append(last_move(t))  # type: ignore[arg-type]
        t = parent(t)
    return "".join(letters)


def addr(word: str) -> Triple:
    """Inverse of address_of: apply the moves of the word to (3,4,5),
    rightmost letter first."""
    moves = {
        "A": lambda t: (t[0] - 2 * t[1] + 2 * t[2], 2 * t[0] - t[1] + 2 * t[2],
                        2 * t[0] - 2 * t[1] + 3 * t[2]),
        "B": lambda t: (t[0] + 2 * t[1] + 2 * t[2], 2 * t[0] + t[1] + 2 * t[2],
                        2 * t[0] + 2 * t[1] + 3 * t[2]),
        "C": lambda t: (-t[0] + 2 * t[1] + 2 * t[2], -2 * t[0] + t[1] + 2 * t[2],
                        -2 * t[0] + 2 * t[1] + 3 * t[2]),
    }
    t: Triple = ROOT
    for letter in reversed(word):
        t = moves[letter](t)
    return t

from typing import Dict, List, Tuple

Triple = Tuple[int, int, int]
ROOT: Triple = (3, 4, 5)
MOVES = "ABC"


def child(letter: str, t: Triple) -> Triple:
    a, b, c = t
    if letter == "A":
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if letter == "B":
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def enumerate_primitive_triples(limit: int) -> Dict[Triple, str]:
    """Every primitive Pythagorean triple with hypotenuse at most `limit`,
    together with its address word.

    Correctness rests on two facts.  (i) The three moves strictly increase the
    hypotenuse, so a node whose hypotenuse already exceeds `limit` can be pruned
    along with its whole subtree.  (ii) The tree is free, so no triple is ever
    produced twice and no duplicate check is needed.  The traversal therefore
    performs exactly one arithmetic step per output triple (plus the pruned
    fringe), which is optimal up to a constant factor."""
    found: Dict[Triple, str] = {}
    stack: List[Tuple[Triple, str]] = [(ROOT, "")]
    while stack:
        t, word = stack.pop()
        if t[2] > limit:
            continue
        found[t] = word
        for letter in MOVES:
            stack.append((child(letter, t), letter + word))
    return found
